def lcs_length(a: str, b: str) -> int:
    # Use the shorter string for the DP columns to save memory
    if len(a) < len(b):
        a, b = b, a

    prev = [0] * (len(b) + 1)

    for i in range(1, len(a) + 1):
        curr = [0] * (len(b) + 1)
        for j in range(1, len(b) + 1):
            if a[i - 1] == b[j - 1]:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(prev[j], curr[j - 1])
        prev = curr

    return prev[-1]
